#!/bin/bash
sed -i 's/BaseUrl = _devOpsOptions.BaseUrl;/BaseUrl = _devOpsOptions.BaseUrl;\n        UseDefaultCredentials = _devOpsOptions.Auth.UseDefaultCredentials;\n        AuthDomain = _devOpsOptions.Auth.Domain ?? "";\n        AuthUsername = _devOpsOptions.Auth.Username ?? "";\n        AuthPassword = _devOpsOptions.Auth.Password ?? "";/' src/AzureDevOps.DesktopManager/ViewModels/MainWindowViewModel.cs

sed -i 's/var newConfig = new AzureDevOpsOptions/var newConfig = new AzureDevOpsOptions\n        {\n            BaseUrl = this.BaseUrl,\n            Collection = this.Collection,\n            ApiVersion = this.ApiVersion,\n            Auth = new AzureDevOpsAuthOptions\n            {\n                UseDefaultCredentials = this.UseDefaultCredentials,\n                Domain = string.IsNullOrWhiteSpace(this.AuthDomain) ? null : this.AuthDomain,\n                Username = string.IsNullOrWhiteSpace(this.AuthUsername) ? null : this.AuthUsername,\n                Password = string.IsNullOrWhiteSpace(this.AuthPassword) ? null : this.AuthPassword\n            }\n        };/' src/AzureDevOps.DesktopManager/ViewModels/MainWindowViewModel.cs
